#!/bin/bash
# collect-r.sh: text results of the re-validation into out/final (no images, no raw serial logs)
B=/srv/euroos/reval-runs; S=$B/scripts; O=$B/out/final; V1=/srv/euroos/val-runs; cd $B; rm -rf $O; mkdir -p $O/drivers
cp ab.sh cm.sh cms.sh kboot-hda.sh tcgmatrix.sh tcgq1.sh tcgboot.sh klatq.sh pw.sh inst.py psum.sh if0sum.py lanes.sh stage3.sh collect-r.sh pr.sh $O/drivers/ 2>/dev/null
CR="KERNEL PANIC|GENERAL PROTECTION|\[idt\] PAGE FAULT|DOUBLE FAULT|panicked at|WATCHDOG|NMI PROBE|timer-probe\] FROZEN"
KEY="^\[root-heap\]|^\[memt\]|^\[aslr\]|^\[rename|^\[linux-rand\]|^\[nmi-bound\]|^\[fair|^\[many-threads\]|^\[churn-fork|^\[hda\]|^\[keyfocus\]|^\[smp\]|^\[ap-tss\]|^\[kwork\]|^\[fuzz\]"
{ echo "# KVM self-test boots of the self-test image of 732e5f5 (v2), R630, 2 vCPU, -nic none, intel-hda + hda-duplex (kboot-hda.sh); 1, 2, 4, 8 GiB; then 4 vCPU 4 GiB (kvm/s4)"; cat kvm/v2/*.res
  for m in 1 2 4 8; do echo; echo "== ${m} GiB"; grep -aE "$KEY" kvm/v2/k-${m}g.log | cut -c1-240; echo "-- FAILED lines:"; grep -a "^\[" kvm/v2/k-${m}g.log | grep -a FAILED | cut -c1-200; echo "-- crash lines: $(grep -aEc "$CR" kvm/v2/k-${m}g.log) lock inversions: $(grep -ac "LOCK ORDER INVERSION" kvm/v2/k-${m}g.log)"; done
  echo; echo "== 4 vCPU 4 GiB (v2, then 3ecde9e)"; cat kvm/s4/*.res; grep -a "^\[kwork\]" kvm/s4/v2-4g.log kvm/s4/b0-4g.log | cut -c1-240; } > $O/kvm-selftest-boots.txt
{ echo "# markers-compare.py, KVM self-test boots: 06e913e (validation 2026-11e, /srv/euroos/val-runs/kvm/v1) and 3ecde9e (b0, this run) -> 732e5f5 (v2)"
  for base in $V1/kvm/v1:06e913e kvm/b0:3ecde9e; do d=${base%%:*}; n=${base##*:}
    for m in 1 2 4 8; do echo; echo "== $n ${m} GiB"; python3 $S/markers-compare.py compare $d/k-${m}g.log kvm/v2/k-${m}g.log 2>&1 | tail -n 25; done; done
  echo; echo "== 3ecde9e 4 vCPU"; python3 $S/markers-compare.py compare kvm/s4/b0-4g.log kvm/s4/v2-4g.log 2>&1 | tail -n 25; } > $O/comparison-kvm.txt
CF="user-smp4-iommu user-smp4-noiommu kernel-smp4 storage-smp4-iommu-1g combined-smp4-iommu-1g user-smp1-iommu user-smp1-noiommu kernel-smp1 storage-smp1-iommu-1g combined-smp1-iommu-1g"
mk() { grep -a -E "^\[[a-z0-9][a-z0-9_./-]*\]" $1 | grep -a -E "✓|FAILED|⬜|→ OK|-> OK|^\[lk\] boot-total|^\[fork\]|^\[boot-time\]"; }
{ echo "# TCG matrix, R630, restrict=on, self-test image of 732e5f5; comparison with validation 2026-11e (06e913e, /srv/euroos/val-runs/tcg/v1)"; cat tcg/v2/queue.txt
  for c in $CF; do L=tcg/v2/$c.log; mk $V1/tcg/v1/$c.log > /tmp/rr-a.m; mk $L > /tmp/rr-b.m; echo "$c: desktop=$(grep -ac "interactive loop started" $L) watchdog=$(grep -ac "WATCHDOG TRIPPED" $L) nmi=$(grep -ac "NMI PROBE" $L) timer-frozen=$(grep -ac "timer-probe\] FROZEN" $L) fault-lines=$(grep -aEc "KERNEL PANIC|\[PANIC\]|panicked at|DOUBLE FAULT|GENERAL PROTECTION FAULT" $L) FAILED-lines=$(grep -a "^\[[a-z0-9][a-z0-9_./-]*\]" $L | grep -ac FAILED) inversions=$(grep -ac "LOCK ORDER INVERSION" $L) | vs 06e913e: $(python3 $S/markers-compare.py compare /tmp/rr-a.m /tmp/rr-b.m 2>&1 | grep -a "WORSE:")"; done; } > $O/tcg-summary.txt
{ echo "# CI q35 matrix, KVM, restrict=on (EK_RESTRICT=1 EK_ACCEL=kvm), self-test image of 732e5f5. First run: the default leg list (nvmeroot and ahciroot are not among the 13 of validation 2026-11e; tpm needs swtpm, which the R630 does not have, the harness crashed there), then the printer leg alone"; grep -a "leg:\|PASS\|FAIL\|swtpm" q35v2/matrix.out | cut -c1-200; echo "--- printer leg alone (q35p)"; grep -a "leg:\|PASS\|FAIL" q35p/matrix.out | cut -c1-200; } > $O/q35-matrix.txt
for n in pub soak input e1000e smp b0; do [ -f runs/gs-$n/report.txt ] || continue
  { echo "# gui-smoke.py, run gs-$n, KVM 4 GiB"; grep -a "gui-smoke\] \(PASS\|FAIL\)" runs/gs-$n.out | cut -c1-200; echo "crash or watchdog lines: $(grep -aEc "KERNEL PANIC|\[PANIC\]|panicked at|DOUBLE FAULT|GENERAL PROTECTION FAULT|\[idt\] PAGE FAULT|WATCHDOG TRIPPED" runs/gs-$n/serial.log)"; echo "FAIL lines: $(grep -ac "gui-smoke\] FAIL" runs/gs-$n.out)"; grep -a "^\[smp\] .*AP(s) idle" runs/gs-$n/serial.log | cut -c1-160; } > $O/gui-smoke-$n.txt
  mk runs/gs-$n/serial.log > /tmp/gs-$n.markers; done
{ echo "# markers-compare.py, public image, gui-smoke KVM 4 vCPU 4 GiB: 3ecde9e (gs-b0) -> 732e5f5 (gs-pub); then 06e913e (validation runs/gs-pub) -> 732e5f5"; python3 $S/markers-compare.py compare /tmp/gs-b0.markers /tmp/gs-pub.markers 2>&1 | tail -n 25
  mk $V1/runs/gs-pub/serial.log > /tmp/gs-v1.markers; echo; python3 $S/markers-compare.py compare /tmp/gs-v1.markers /tmp/gs-pub.markers 2>&1 | tail -n 25
  echo; echo "# [smp] AP lines (06e913e, 3ecde9e, 732e5f5):"; grep -a "^\[smp\] .*AP(s) idle" $V1/runs/gs-pub/serial.log runs/gs-b0/serial.log runs/gs-pub/serial.log | cut -c1-200; echo "# [kwork] line (732e5f5 public image 4 vCPU):"; grep -a "^\[kwork\]" runs/gs-pub/serial.log | cut -c1-200; } > $O/comparison-public.txt
cp wizard.out $O/wizard-install-test.txt
{ for m in plain inject ro0; do echo "== MODE=$m (self-test image)"; grep -a "ro-install\] \(PASS\|FAIL\)" roi-$m.out | cut -c1-200; done; } > $O/ro-install-test.txt
{ echo "# inst.py: phase 0 of rename-persist.py alone, ten at once on eight host CPUs (6-9, 26-29); public image of 732e5f5"; for f in inst/v2-*.out; do cut -c1-62 $f; done | sort | uniq -c; } > $O/installs-side-by-side.txt
cp rp.out $O/rename-persist.txt
{ echo "# boot-time.py, public images, KVM 2 vCPU 2 GiB, pin 18-19 (siblings idle), alternating v2 (732e5f5), b0 (3ecde9e) and v1 (06e913e); desktop = s from QEMU start to interactive loop started; the soak (CPUs 30-33) and the browser session (CPUs 0-1) ran beside it on other cores"; cat bt/kvm-ab.txt; python3 $B/btsum.py bt/kvm-ab.txt; } > $O/boot-time.txt
{ echo "# short-boots.sh: boots of the self-test image of 732e5f5 until [fuzz] Linux-ABI (KVM, 2 vCPU, 2 GiB, -nic none), 12 lanes of two CPUs on cores 4-9 and 14-19 AND their SMT siblings (24-29, 34-39): every lane shares its cores with another guest (the load that reproduced BUG-273); 9 boots per lane"
  echo "boots: $(cat short/*/summary.txt | grep -c ^boot=)  end=marker: $(cat short/*/summary.txt | grep -c "end=marker")  with a FAILED line: $(cat short/*/summary.txt | grep ^boot= | grep -vc "failed-lines=0 ")  crash lines in any: $(cat short/*/summary.txt | grep ^boot= | grep -vc crash-lines=0)"
  echo "CSPRNG seeded: $(cat short/*/summary.txt | grep -c "seeded=1 not-seeded=0")  [3d8]/[3d7] OK: $(cat short/*/summary.txt | grep -c "3d8 ok=1 failed=0 | 3d7 ok=1 failed=0")"
  echo "seconds to the [fuzz] line: $(cat short/*/summary.txt | grep -o "secs=[0-9.]*" | cut -d= -f2 | sort -n | awk -f $B/med.awk)"; } > $O/short-boots.txt
{ echo "# keylat: chrome-smoke --only perf (30 keys), browser images, 3ecde9e (b0) against 732e5f5 (v2), four runs at a time, tmpfs work dirs, siblings idle, smp 4 (b0 CPUs 34-37, v2 2-5) and smp 2 (b0 38-39, v2 28-29); median key to screen ms"
  for r in 1 2 3; do echo "## round $r"; bash psum.sh kq$r-b0-4 kq$r-v2-4 kq$r-b0-2 kq$r-v2-2 2>&1 | grep "^== kq.*median" | cut -c1-120; done; } > $O/keylat.txt
rpt() { [ -f runs/$1.out ] || return; echo "# $2"; grep -a "gui-smoke\] \(FAIL\)\|chrome-smoke\] \(PASS\|FAIL\|CRASH\|starts\)\|wmvideo\] " runs/$1.out | cut -c1-260; L=$B/runs/$1/serial.log; [ -f $L ] && echo "-- aborts=$(grep -ac "^\[abort\]" $L) spawn-refused=$(grep -ac spawn-refused $L) oom=$(grep -ac "^\[oom\]" $L) timer-frozen=$(grep -ac "timer-probe\] FROZEN" $L) crash/watchdog=$(grep -aEc "$CR" $L)"; }
{ echo "# chrome-smoke --starts 20 --smp 2: 732e5f5 browser image and, beside it at the same time, 3ecde9e"; grep -a "starts:" runs/starts20-v2.out | cut -c1-200; echo "timer-probe FROZEN: $(cat /dev/shm/rv/starts20-v2/start-*/serial.log 2>/dev/null | grep -ac "timer-probe\] FROZEN")"; echo "# 3ecde9e"; grep -a "starts:" runs/starts20-b0.out | cut -c1-200; echo "timer-probe FROZEN: $(cat /dev/shm/rv/starts20-b0/start-*/serial.log 2>/dev/null | grep -ac "timer-probe\] FROZEN")"; } > $O/chrome-starts20.txt
{ rpt sites3 "chrome-smoke --only sites --rounds 3 --smp 2, browser image of 732e5f5, one session (consent banners clicked by the harness)"; echo; rpt sites-smp "informational: smpuser=on, --smp 4, same matrix"; } > $O/chrome-site-matrix.txt
rpt interact "chrome-smoke --only interact --smp 2" > $O/chrome-interact.txt
rpt localvideo2 "chrome-smoke --only localvideo --smp 2 --local-port 18781 (H.264/AAC fails by design: open codecs only; the first attempt hit a port clash with the soak, see README)" > $O/chrome-localvideo.txt
grep -a "ok   local video vp9+opus" runs/localvideo2.out | cut -c1-330 >> $O/chrome-localvideo.txt
{ rpt wm480b "wmvideo.py: Wikimedia Big Buck Bunny 480p VP9 + Opus, 2 x 90 s, --smp 2, 6 GiB"; grep -a "site video-play" runs/wm480b.out | grep -o "round [0-9]*: 90 s\|picture.*windows" | paste - - ; echo "(first attempt with the default 360p URL: the file does not play, 0 of 22 screendumps differ; runs/wm360-failed.out, not counted)"; } > $O/chrome-wikimedia-480p.txt
{ echo "# chrome-mem-soak.py --no-video --free-video-seconds 0 --hours 2 --local-video-dir (vp9.webm only) --local-seconds 60, browser image of 732e5f5, 8 GiB, 2 vCPU, CPUs 0-1 (siblings idle)"; grep -a "chrome-mem-soak\]\|chrome-smoke\] \(PASS\|FAIL\|CRASH\)" runs/soak2h.out | cut -c1-260 | tail -n 16
  L=runs/soak2h/serial.log; echo "-- aborts=$(grep -ac "^\[abort\]" $L) spawn-refused=$(grep -ac spawn-refused $L) oom=$(grep -ac "^\[oom\]" $L) timer-frozen=$(grep -ac "timer-probe\] FROZEN" $L) crash/watchdog=$(grep -aEc "$CR" $L)"; python3 $S/mem-curve.py $L runs/soak2h.out 2>&1 | grep -a "owner\|heap_used\|verdict\|census samples" ; } > $O/chrome-soak2h.txt
python3 $S/mem-curve.py runs/soak2h/serial.log runs/soak2h.out > $O/chrome-soak2h-curve.txt 2>&1
w=soak2/w; L=$(ls $w/loadtest-serial-*.log | head -1); cp $w/loadtest-results.csv $O/r630-soak.csv
{ echo "# Soak, R630 KVM, self-test image of 732e5f5, clean second run: loadtest.py --kvm --smp 4 --nic e1000e --restrict --nmi-on-hang --mem 16G --disks 8G --host-http --hammer 4 --procs 32 --scenario soak --soak-churn-proc 8 --duration 7500, CPUs 30-33 (siblings 10-13 idle)"
  python3 $S/soak_compare.py "732e5f5=$w/loadtest-results.csv" "06e913e=$V1/soakv2/w/loadtest-results.csv" 2>&1
  for k in "KERNEL PANIC" "GENERAL PROTECTION" "[idt] PAGE FAULT" "DOUBLE FAULT" "NMI PROBE" "WATCHDOG TRIPPED" "timer-probe] FROZEN" "LOCK ORDER INVERSION" "[oom]" "[spawn-refused]"; do echo "  $k: $(grep -acF "$k" $L)"; done
  echo "  [churn-proc] verdict lines: $(grep -ac "^\[churn-proc\]" $L), with FAILED: $(grep -a "^\[churn-proc\]" $L | grep -c FAILED)"; grep -a "hammer (inbound" soak2/out.txt | cut -c1-420
  echo "--- first (disturbed) run, soak/: see README"; python3 $S/soak_compare.py "first-run=soak/w/loadtest-results.csv" 2>&1 | head -8; } > $O/r630-soak-summary.txt
{ echo "# [fair] hogtest 5 10 8, KVM 4 vCPU 4 GiB, e1000e restrict; first-round task 0 share of each boot (self-test image of 732e5f5; fair/ = beside the soak, fairq/ = quiet machine if present)"; for d in fair/f* fairq/*; do [ -d $d ] && echo "$d: $(grep -a "^\[fair\]" $d/loadtest-serial-*.log | head -1 | grep -o "[0-9.]* s, task 0 share [0-9]* %" | cut -c1-80)"; done; } > $O/fair.txt
ls $O
